    // Note contract

    // It has two execution paths:

    // spend: full spending or with change

    // redeem:

    // to create a note, ...

    // box data:
    // R4 - history of ownership (under AVL+ tree),
    //      tree contains reserveId as a key, signature as value,
    //      and message is note value and token id
    // R5 - current holder of the note (public key given as a group element)
    // R6 - current length of the chain (as long int)
    // R7 - note value (as long int)

    val g: GroupElement = groupGenerator

    val history = SELF.R4[AvlTree].get

    val action = getVar[Byte](0).get

    val reserve = CONTEXT.dataInputs(0)
    val reserveId = reserve.tokens(0)._1

    if (action >= 0) {
      // spending path

      val holder = SELF.R5[GroupElement].get

      val selfOutput = OUTPUTS(action)

      // Message to be signed is position + note amount + note id
      val position = SELF.R6[Long].get
      val noteValueBytes = longToByteArray(SELF.R7[Long].get)
      val positionBytes = longToByteArray(position)
      val message = positionBytes ++ noteValueBytes ++ SELF.id

      // Computing challenge
      val e: Coll[Byte] = blake2b256(message) // weak Fiat-Shamir - todo: should be strong
      val eInt = byteArrayToBigInt(e) // challenge as big integer

      // a of signature in (a, z)
      val a = getVar[GroupElement](1).get
      val aBytes = a.getEncoded

      // z of signature in (a, z)
      val zBytes = getVar[Coll[Byte]](2).get
      val z = byteArrayToBigInt(zBytes)

      val properHolder = holder == reserve.R4[GroupElement].get

      // Signature is valid if g^z = a * x^e
      val properSignature = (g.exp(z) == a.multiply(holder.exp(eInt))) && properHolder

      val keyBytes = longToByteArray(position) ++ reserveId

      val valueBytes = aBytes ++ zBytes

      val keyVal = (keyBytes, valueBytes)
      val proof = getVar[Coll[Byte]](3).get

      val nextTree: Option[AvlTree] = history.insert(Coll(keyVal), proof)
      // This will fail if the operation failed or the proof is incorrect due to calling .get on the Option
      val outputDigest: Coll[Byte] = nextTree.get.digest

      def nextNoteCorrect(noteOut: Box): Boolean = {
        val insertionPerformed = noteOut.R4[AvlTree].get.digest == outputDigest
        val sameScript = noteOut.propositionBytes == SELF.propositionBytes
        val nextHolderDefined = noteOut.R5[GroupElement].isDefined
        val valuePreserved = noteOut.value >= SELF.value
        val positionIncreased = noteOut.R6[Long].get == (position + 1)

        positionIncreased && insertionPerformed && sameScript && nextHolderDefined && valuePreserved
      }

      val changeIdx = getVar[Byte](4) // optional index of change output

      val selfValue = SELF.R6[Long].get
      val selfOutValue = selfOutput.R6[Long].get

      val outputsValid = if(changeIdx.isDefined) {
        val changeOutput = OUTPUTS(changeIdx.get)

        val changeOutValue = changeOutput.R6[Long].get

        (selfOutValue + changeOutValue) <= selfValue && // burn allowed
            selfOutValue > 0 &&
            changeOutValue > 0 &&
            nextNoteCorrect(selfOutput) &&
            nextNoteCorrect(changeOutput)
      } else {
        (selfOutValue == selfValue) && nextNoteCorrect(selfOutput)
      }

      sigmaProp(properSignature && outputsValid)
    } else {
      // redemption path

      // called by setting action variable to any negative value, -1 considered as standard by offchain apps

      val redeemOutput = OUTPUTS(0)
      val redemptionCorrect = redeemOutput.tokens(0)._1 == fromBase58("") //todo: redemption token id
      val historyCorrect = redeemOutput.R4[AvlTree].get == SELF.R4[AvlTree].get
      val redemptionDeadlineValid = redeemOutput.R5[Int].get >= HEIGHT + 1440

      sigmaProp(redemptionCorrect && historyCorrect && redemptionDeadlineValid)
    }

}

{
 // contract which is producing redemption contract boxes
 // it holds redemption contract tokens and releasing it
 // one token can be released when the contract is invoked
 // if an output with the token bound to the redemption contract
 //
 // TOKENS
 // #0 - contract NFT
 // #1 - redemption request token

 val redeemScriptHash = fromBase58("")

 val selfOutput = OUTPUTS(0)
 val redemptionRequestOutput = OUTPUTS(1)

 val redemptionRequestTokenId = SELF.tokens(1)._1
 val redemptionRequestTokensInSelf = SELF.tokens(1)._2

 val selfOutCorrect = selfOutput.value >= SELF.value && selfOutput.tokens(0) == SELF.tokens(0) &&
                        selfOutput.tokens(1)._1 == redemptionRequestTokenId &&
                        selfOutput.tokens(1)._2 == redemptionRequestTokensInSelf - 1

 val redemptionTokenCorrect = redemptionRequestOutput.tokens(0)._1 == redemptionRequestTokenId &&
                                redemptionRequestOutput.tokens(0)._2 == 1

 val properCollateral = redemptionRequestOutput.value == 2000000000

 val properDeadline = redemptionRequestOutput.R8[Int].get >= HEIGHT + 720 // one day for contestation

 val properRedeemPosition = redemptionRequestOutput.R6[(Long, Coll[Byte])].get._1 <= redemptionRequestOutput.R5[Long].get

 val redeemR7 = redemptionRequestOutput.R7[(Long, Boolean)].get

 val redeemR7Correct = redeemR7._1 == -1 && redeemR7._2 == false

 val redemptionScriptCorrect = blake2b256(redemptionRequestOutput.propositionBytes) == redeemScriptHash

 val redemptionRequestCorrect = redemptionTokenCorrect && properCollateral && properDeadline &&
                                properRedeemPosition && redeemR7Correct && redemptionScriptCorrect

 sigmaProp(selfOutCorrect && redemptionRequestCorrect)

}

{
	def getSellerPk(box: Box)              = box.R4[Coll[SigmaProp]].get(0)
	def getPoolPk(box: Box)                = box.R4[Coll[SigmaProp]].get(1)
	def unlockHeight(box: Box)             = box.R5[Int].get

	if(HEIGHT > unlockHeight(SELF)){
		getSellerPk(SELF)
	}else{
		getSellerPk(SELF) // && getPoolPk(SELF)
	}
}

{
  // Contract which is releasing GORT to developers (Gold cooperative), 1 ERG per block.
  // It supports two actions: top-up and withdrawal

  // Registers:
  // R4 (int) - last payment height
  // R5 (SigmaProp) - auth

  // tokens:
  // #0 - box id NFT
  // #1 - GORT

  // context vars:
  // #0 - output index of SELF
  // #1 - action (top-up / withdrawal)

  val lastHeight = SELF.R4[Int].get // last payout height

  val selfOutIndex = getVar[Short](0).get

  val selfOut = OUTPUTS(selfOutIndex)

  // strip header byte from trees
  val selfOutTree = selfOut.propositionBytes.slice(1, selfOut.propositionBytes.size)
  val selfInTree = SELF.propositionBytes.slice(1, SELF.propositionBytes.size)

  val commonPreservationRules =
    selfOut.tokens(0) == SELF.tokens(0) && // NFT preserved
    selfOut.tokens(1)._1 == SELF.tokens(1)._1 && // GORT token id preserved
    selfOutTree == selfInTree && // script preserved
    selfOut.value >= SELF.value // ERG value preserved or increased

  val action = getVar[Byte](1).get

  if (action == 0) {  // top-up:
    sigmaProp(
        commonPreservationRules &&
        selfOut.tokens(1)._2 > SELF.tokens(1)._2 && // GORTs must be added
        selfOut.R4[Int].get == lastHeight && // payout height preserved
        selfOut.R5[SigmaProp].get == SELF.R5[SigmaProp].get // auth preserved
    )
  } else {  // withdrawal
    val newHeight = selfOut.R4[Int].get
    sigmaProp(
        commonPreservationRules &&
        SELF.tokens(1)._2 > selfOut.tokens(1)._2 && // GORTs withdrawn
        SELF.tokens(1)._2 - selfOut.tokens(1)._2 <= newHeight - lastHeight && // <= 1 GORT per block can be released
        newHeight > lastHeight && // payout height increased
        newHeight <= HEIGHT   // can't take rewards from future
        // R5 is not checked here so could be changed
    ) && SELF.R5[SigmaProp].get // signature from proposition stored in R5 is needed to withdraw (and possibly update payout data)
  }
}

